/* ===== 1.4.5 (pprof45): PresentPro's deck without the window: themes, layouts, slides drawn as page elements (for the
   editor, the thumbnails, presenting and pictures), .RDECK (version 2, and version 1 from the old Presentations app),
   PowerPoint .pptx (written and read through JSZip) and templates.
   A deck: {v:2,size:'16:9'|'4:3',theme,master:{footer,date,num,logo},slides:[slide],sections:[{name,at}]}. The slide is
   960 × 540 units (720 × 540 at 4:3); a unit is a point, so a .pptx carries them as 12,700 EMU each.
   A slide: {id,layout,bg,objs:[obj],notes,hidden,tr:{t,d},after}. An object: {id,t:'text'|'shape'|'img'|'table'|'chart'|
   'icon',x,y,w,h,rot,…,anim:{t,on,d}}. Text is a small, checked subset of HTML (ppClean); nothing else from a file is
   used as HTML. ===== */
const PP_THEMES={
 office:{name:'Office',bg:'#ffffff',fg:'#262626',title:'#1f1f1f',acc:['#4472c4','#ed7d31','#a5a5a5','#ffc000','#5b9bd5','#70ad47'],tf:'Calibri Light',bf:'Calibri'},
 slate:{name:'Slate',bg:'linear-gradient(135deg,#1e293b,#334155)',fg:'#e2e8f0',title:'#ffffff',acc:['#38bdf8','#f472b6','#a3e635','#fbbf24','#c084fc','#fb7185'],tf:'Segoe UI',bf:'Segoe UI'},
 ocean:{name:'Ocean',bg:'linear-gradient(160deg,#0c4a6e,#0e7490)',fg:'#e0f2fe',title:'#ffffff',acc:['#67e8f9','#fde047','#86efac','#fca5a5','#a5b4fc','#fdba74'],tf:'Georgia',bf:'Verdana'},
 sunrise:{name:'Sunrise',bg:'linear-gradient(160deg,#fff7ed,#fde68a)',fg:'#422006',title:'#9a3412',acc:['#ea580c','#dc2626','#ca8a04','#65a30d','#0891b2','#7c3aed'],tf:'Trebuchet MS',bf:'Trebuchet MS'},
 forest:{name:'Forest',bg:'#f0fdf4',fg:'#14532d',title:'#166534',acc:['#16a34a','#65a30d','#0d9488','#ca8a04','#b45309','#0369a1'],tf:'Georgia',bf:'Calibri'},
 berry:{name:'Berry',bg:'linear-gradient(135deg,#4a044e,#831843)',fg:'#fce7f3',title:'#ffffff',acc:['#f0abfc','#fda4af','#fcd34d','#a5f3fc','#c4b5fd','#bef264'],tf:'Garamond',bf:'Verdana'},
 paper:{name:'Paper',bg:'#faf7f0',fg:'#3f3f46',title:'#18181b',acc:['#b91c1c','#1d4ed8','#15803d','#a16207','#7e22ce','#0f766e'],tf:'Palatino Linotype',bf:'Georgia'},
 midnight:{name:'Midnight',bg:'#0b1020',fg:'#cbd5e1',title:'#f8fafc',acc:['#818cf8','#22d3ee','#f472b6','#facc15','#4ade80','#fb923c'],tf:'Segoe UI',bf:'Segoe UI'},
 citrus:{name:'Citrus',bg:'#ffffff',fg:'#1f2937',title:'#047857',acc:['#84cc16','#f59e0b','#10b981','#ef4444','#06b6d4','#8b5cf6'],tf:'Verdana',bf:'Verdana',band:'#d9f99d'},
 mono:{name:'Monochrome',bg:'#ffffff',fg:'#111111',title:'#000000',acc:['#000000','#525252','#a3a3a3','#d4d4d4','#404040','#737373'],tf:'Arial',bf:'Arial',band:'#000000'},
 coral:{name:'Coral',bg:'linear-gradient(180deg,#fff1f2,#ffe4e6)',fg:'#4c0519',title:'#be123c',acc:['#f43f5e','#fb923c','#14b8a6','#6366f1','#eab308','#64748b'],tf:'Comic Sans MS',bf:'Trebuchet MS'},
 steel:{name:'Steel',bg:'linear-gradient(180deg,#f8fafc,#e2e8f0)',fg:'#1e293b',title:'#0f172a',acc:['#2563eb','#475569','#0891b2','#d97706','#16a34a','#dc2626'],tf:'Tahoma',bf:'Tahoma',band:'#2563eb'}};
const PP_LAYOUTS=[['title','Title slide'],['content','Title and content'],['two','Two content'],['compare','Comparison'],['section','Section header'],['titleonly','Title only'],['blank','Blank'],['picture','Picture with caption']];
const PP_SHAPES=[['rect','Rectangle'],['round','Rounded rectangle'],['ellipse','Ellipse'],['tri','Triangle'],['rtri','Right triangle'],['diamond','Diamond'],['pent','Pentagon'],['hex','Hexagon'],['chevron','Chevron'],['rarrow','Arrow right'],['larrow','Arrow left'],['uarrow','Arrow up'],['darrow','Arrow down'],['star','Star'],['callout','Callout'],['bubble','Speech bubble'],['line','Line'],['arrow','Arrow line'],['conn','Connector']];
const PP_ICONS=['⭐','✅','❌','⚠️','💡','📈','📉','📊','🎯','🚀','🔒','🔑','💬','📌','📅','⏰','🌍','🏠','👥','👤','❤️','👍','🔔','📷','🎵','💰','🛒','🔧','⚙️','🏆','📚','✏️','🎓','🌱','☀️','🌙','⚡','🔥','💧','🍎'];
const PP_TRANS=[['none','None'],['fade','Fade'],['push','Push'],['wipe','Wipe'],['cover','Cover'],['zoom','Zoom'],['morph','Move (objects glide to their places)']];
const PP_ANIMS=[['','None'],['appear','Appear'],['fade','Fade'],['fly','Fly in'],['zoom','Zoom'],['wipe','Wipe']];
const ppSize=D=>D.size=='4:3'?[720,540]:[960,540];
const ppId=()=>Math.random().toString(36).slice(2,9);
/* ---- text: only these tags and styles survive, from files, the clipboard and the editor ---- */
const PP_TAGS=new Set(['P','DIV','BR','B','STRONG','I','EM','U','S','STRIKE','SPAN','UL','OL','LI','SUB','SUP','FONT']);
const PP_CSS=new Set(['color','background-color','font-size','font-family','font-weight','font-style','text-decoration','text-decoration-line','text-align','line-height','margin-left','padding-left']);
function ppClean(html){const d=new DOMParser().parseFromString('<body>'+String(html||'')+'</body>','text/html');const out=document.createElement('div');
 const walk=(src,dst)=>{for(const n of src.childNodes){if(n.nodeType==3){dst.appendChild(document.createTextNode(n.nodeValue));continue}if(n.nodeType!=1)continue;
   if(/^(SCRIPT|STYLE|TEMPLATE|NOSCRIPT|IFRAME|OBJECT|EMBED|SVG|MATH|TITLE|HEAD|SELECT|TEXTAREA)$/i.test(n.tagName))continue;if(!PP_TAGS.has(n.tagName)){walk(n,dst);continue}const e=document.createElement(n.tagName=='FONT'?'SPAN':n.tagName);
   const st=[];if(n.style)for(let i=0;i<n.style.length;i++){const k=n.style[i];if(PP_CSS.has(k)){const v=n.style.getPropertyValue(k);if(v&&!/url\(|expression|javascript:|^(initial|inherit|unset|revert)$/i.test(v.trim()))st.push(k+':'+v)}}
   if(n.tagName=='FONT'){const c=n.getAttribute('color');if(c&&/^#?[\w]+$/.test(c))st.push('color:'+c);const f=n.getAttribute('face');if(f&&/^[\w ,'-]+$/.test(f))st.push('font-family:'+f)}
   if(st.length)e.setAttribute('style',st.join(';'));walk(n,e);dst.appendChild(e)}};walk(d.body,out);return out.innerHTML}
const ppText=html=>{const d=document.createElement('div');d.innerHTML=ppClean(String(html||'').replace(/<\/(p|div|li)>/gi,'</$1>\n').replace(/<br\s*\/?>/gi,'\n'));return d.textContent.replace(/\n{2,}/g,'\n').trim()};
const ppEsc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ppLines=t=>String(t||'').split('\n').map(l=>`<p>${ppEsc(l)||'<br>'}</p>`).join('');
const ppBullets=t=>{const ls=String(t||'').split('\n').filter(l=>l.trim());return ls.length?'<ul>'+ls.map(l=>`<li>${ppEsc(l.replace(/^[-•*]\s*/,''))}</li>`).join('')+'</ul>':'<ul><li><br></li></ul>'};
/* ---- placeholders of each layout ---- */
function ppLayout(D,layout,o){o=o||{};const[W,H]=ppSize(D);const th=PP_THEMES[D.theme]||PP_THEMES.office;const m=W*.06;
 const T=(x,y,w,h,html,fs,extra)=>({id:ppId(),t:'text',x,y,w,h,html,fs,ph:'title',font:th.tf,color:th.title,...(extra||{})});const B=(x,y,w,h,html,fs,extra)=>({id:ppId(),t:'text',x,y,w,h,html,fs,ph:'body',font:th.bf,color:th.fg,...(extra||{})});
 switch(layout){
  case'title':return[T(m,H*.28,W-2*m,H*.24,ppLines(o.title??''),Math.round(W/16),{align:'center',valign:'bottom',hint:'Click to add a title'}),B(m*2,H*.55,W-4*m,H*.16,ppLines(o.sub??''),Math.round(W/40),{align:'center',ph:'sub',hint:'Click to add a subtitle'})];
  case'section':return[T(m,H*.3,W-2*m,H*.22,ppLines(o.title??''),Math.round(W/20),{valign:'bottom',hint:'Click to add a section title'}),B(m,H*.54,W-2*m,H*.14,ppLines(o.sub??''),Math.round(W/44),{ph:'sub',hint:'Click to add text'})];
  case'titleonly':return[T(m,H*.06,W-2*m,H*.16,ppLines(o.title??''),Math.round(W/26),{valign:'middle',hint:'Click to add a title'})];
  case'blank':return[];
  case'two':return[T(m,H*.06,W-2*m,H*.16,ppLines(o.title??''),Math.round(W/26),{valign:'middle',hint:'Click to add a title'}),B(m,H*.26,(W-3*m)/2,H*.64,ppBullets(o.body??''),Math.round(W/40),{hint:'Click to add text'}),B(m*2+(W-3*m)/2,H*.26,(W-3*m)/2,H*.64,ppBullets(o.body2??''),Math.round(W/40),{hint:'Click to add text'})];
  case'compare':return[T(m,H*.06,W-2*m,H*.14,ppLines(o.title??''),Math.round(W/26),{valign:'middle',hint:'Click to add a title'}),B(m,H*.22,(W-3*m)/2,H*.1,ppLines(o.h1??''),Math.round(W/36),{bold:1,ph:'head',hint:'Heading'}),B(m*2+(W-3*m)/2,H*.22,(W-3*m)/2,H*.1,ppLines(o.h2??''),Math.round(W/36),{bold:1,ph:'head',hint:'Heading'}),B(m,H*.34,(W-3*m)/2,H*.56,ppBullets(o.body??''),Math.round(W/42),{hint:'Click to add text'}),B(m*2+(W-3*m)/2,H*.34,(W-3*m)/2,H*.56,ppBullets(o.body2??''),Math.round(W/42),{hint:'Click to add text'})];
  case'picture':return[T(m,H*.72,W*.4,H*.12,ppLines(o.title??''),Math.round(W/32),{valign:'bottom',hint:'Click to add a title'}),B(m,H*.84,W*.4,H*.1,ppLines(o.sub??''),Math.round(W/52),{ph:'sub',hint:'Click to add a caption'}),{id:ppId(),t:'img',x:W*.5,y:H*.08,w:W*.44,h:H*.84,img:o.img||'',ph:'pic',hint:'Click to add a picture'}];
  default:return[T(m,H*.06,W-2*m,H*.16,ppLines(o.title??''),Math.round(W/26),{valign:'middle',hint:'Click to add a title'}),B(m,H*.26,W-2*m,H*.66,ppBullets(o.body??''),Math.round(W/36),{hint:'Click to add text'})]}}
function ppSlide(D,layout,o){return{id:ppId(),layout:layout||'content',bg:null,objs:ppLayout(D,layout||'content',o),notes:(o&&o.notes)||'',hidden:false,tr:{t:'none',d:.6}}}
function ppDeckNew(theme){const D={v:2,size:'16:9',theme:theme||'office',master:{footer:'',date:false,num:false,logo:null},slides:[],sections:[]};D.slides.push(ppSlide(D,'title'));return D}
/* ---- drawing a slide as page elements; the same function draws the editor, the thumbnails and the show ---- */
function ppBgCss(D,s){const th=PP_THEMES[D.theme]||PP_THEMES.office;const b=s&&s.bg;if(!b)return th.bg;if(b.t=='color')return b.c;if(b.t=='grad')return`linear-gradient(${b.a??135}deg,${b.c},${b.c2})`;if(b.t=='img'&&b.img)return`center/cover no-repeat url("${b.img}")`;return th.bg}
function ppShapePath(k,w,h){const p=(...a)=>'M'+a.map(x=>x.join(',')).join(' L')+' Z';const r=Math.min(w,h);
 switch(k){case'round':{const q=r*.16;return`M${q},0 H${w-q} Q${w},0 ${w},${q} V${h-q} Q${w},${h} ${w-q},${h} H${q} Q0,${h} 0,${h-q} V${q} Q0,0 ${q},0 Z`}
  case'ellipse':return`M0,${h/2} A${w/2},${h/2} 0 1 1 ${w},${h/2} A${w/2},${h/2} 0 1 1 0,${h/2} Z`;case'tri':return p([w/2,0],[w,h],[0,h]);case'rtri':return p([0,0],[w,h],[0,h]);case'diamond':return p([w/2,0],[w,h/2],[w/2,h],[0,h/2]);
  case'pent':return p([w/2,0],[w,h*.38],[w*.81,h],[w*.19,h],[0,h*.38]);case'hex':return p([w*.25,0],[w*.75,0],[w,h/2],[w*.75,h],[w*.25,h],[0,h/2]);case'chevron':return p([0,0],[w*.75,0],[w,h/2],[w*.75,h],[0,h],[w*.25,h/2]);
  case'rarrow':return p([0,h*.3],[w*.65,h*.3],[w*.65,0],[w,h/2],[w*.65,h],[w*.65,h*.7],[0,h*.7]);case'larrow':return p([w,h*.3],[w*.35,h*.3],[w*.35,0],[0,h/2],[w*.35,h],[w*.35,h*.7],[w,h*.7]);
  case'uarrow':return p([w*.3,h],[w*.3,h*.35],[0,h*.35],[w/2,0],[w,h*.35],[w*.7,h*.35],[w*.7,h]);case'darrow':return p([w*.3,0],[w*.3,h*.65],[0,h*.65],[w/2,h],[w,h*.65],[w*.7,h*.65],[w*.7,0]);
  case'star':{const pts=[];for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?.4:1;pts.push([w/2+Math.cos(a)*w/2*rr,h/2+Math.sin(a)*h/2*rr*1.05+h*.03])}return p(...pts)}
  case'callout':return p([0,0],[w,0],[w,h*.75],[w*.45,h*.75],[w*.2,h],[w*.25,h*.75],[0,h*.75]);
  case'bubble':return`M${w/2},0 C${w*1.02},0 ${w*1.02},${h*.75} ${w/2},${h*.75} C${w*.42},${h*.75} ${w*.34},${h*.74} ${w*.27},${h*.72} L${w*.08},${h} L${w*.15},${h*.66} C${-w*.02},${h*.56} ${-w*.02},0 ${w/2},0 Z`;
  default:return`M0,0 H${w} V${h} H0 Z`}}
function ppObjEl(D,s,o,opt){const th=PP_THEMES[D.theme]||PP_THEMES.office;const el=document.createElement('div');el.className='pp-o pp-'+o.t;el.dataset.id=o.id;
 /* an empty placeholder is only shown while editing (as PowerPoint does) */if(!(opt&&opt.hints)&&o.ph&&(o.t=='text'&&!ppText(o.html)&&!o.fill&&!o.line||o.t=='img'&&!o.img)){el.style.display='none';return el}
 el.style.cssText=`left:${o.x}px;top:${o.y}px;width:${o.w}px;height:${o.h}px;${o.rot?`transform:rotate(${o.rot}deg);`:''}${o.op!=null&&o.op<1?`opacity:${o.op};`:''}`;
 const shadow=o.shadow?'filter:drop-shadow(3px 4px 4px rgba(0,0,0,.35));':'';
 if(o.t=='text'||o.t=='shape'){let svg='';if(o.t=='shape'){const ln=o.shape=='line'||o.shape=='arrow'||o.shape=='conn';const fill=ln?'none':(o.fill??th.acc[0]),stroke=o.line??(ln?th.fg:'none'),lw=o.lw??(ln?3:0);
   const d=ln?`M0,${o.h/2} L${o.w},${o.h/2}`:ppShapePath(o.shape,o.w,o.h);const mk=o.shape=='arrow'||o.shape=='conn'&&o.arrow!==false?`<defs><marker id='m${o.id}' viewBox='0 0 10 10' refX='9' refY='5' markerWidth='5' markerHeight='5' orient='auto'><path d='M0,0 L10,5 L0,10 z' fill='${stroke}'/></marker></defs>`:'';
   svg=`<svg class='pp-sv' width='${o.w}' height='${o.h}' viewBox='0 0 ${o.w} ${o.h}' style='overflow:visible;${shadow}'>${mk}<path d='${d}' fill='${ppEsc(fill)}' stroke='${ppEsc(stroke)}' stroke-width='${lw}'${o.dash?` stroke-dasharray='${lw*3},${lw*2}'`:''}${mk?` marker-end='url(#m${o.id})'`:''} vector-effect='non-scaling-stroke'/></svg>`}
  else if(o.fill||o.line)el.style.cssText+=`background:${o.fill||'transparent'};${o.line?`border:${o.lw||1}px solid ${o.line};`:''}${shadow}`;
  const tc=document.createElement('div');tc.className='pp-tx';const pad=o.t=='shape'?8:6;
  tc.style.cssText=`padding:${pad}px ${pad+2}px;font-family:"${o.font||(o.ph=='title'?th.tf:th.bf)}",Calibri,Carlito,Arial,sans-serif;font-size:${o.fs||24}px;color:${o.color||(o.t=='shape'?'#fff':th.fg)};text-align:${o.align||(o.t=='shape'?'center':'left')};justify-content:${{top:'flex-start',middle:'center',bottom:'flex-end'}[o.valign||(o.t=='shape'?'middle':'top')]};${o.bold?'font-weight:bold;':''}${o.ls?`line-height:${o.ls};`:''}`;
  const inner=document.createElement('div');inner.className='pp-ti';inner.innerHTML=ppClean(o.html||'');tc.appendChild(inner);
  if(opt&&opt.hints&&o.hint&&!ppText(o.html)){const h=document.createElement('div');h.className='pp-hint';h.textContent=o.hint;tc.appendChild(h)}
  el.insertAdjacentHTML('afterbegin',svg);el.appendChild(tc)}
 else if(o.t=='img'){if(o.img){const im=document.createElement('img');im.src=o.img;im.draggable=false;const c=o.crop||{};
   if(c.l||c.t||c.r||c.b){const wf=1-(c.l||0)-(c.r||0),hf=1-(c.t||0)-(c.b||0);im.style.cssText=`position:absolute;width:${100/wf}%;height:${100/hf}%;left:${-100*(c.l||0)/wf}%;top:${-100*(c.t||0)/hf}%;max-width:none`;el.style.overflow='hidden'}else im.style.cssText=`width:100%;height:100%;object-fit:${o.fit||'fill'}`;
   if(o.br!=null&&o.br!=100||o.ct!=null&&o.ct!=100)im.style.filter=`brightness(${(o.br??100)/100}) contrast(${(o.ct??100)/100})`;el.appendChild(im)}
  else if(opt&&opt.hints){el.innerHTML=`<div class='pp-imgph'>🖼<br>${ppEsc(o.hint||'Picture')}</div>`}
  if(o.line)el.style.cssText+=`outline:${o.lw||2}px solid ${o.line};outline-offset:-${o.lw||2}px;`;if(o.round)el.style.borderRadius=o.round+'px',el.style.overflow='hidden';if(o.shadow)el.style.boxShadow='4px 5px 10px rgba(0,0,0,.35)'}
 else if(o.t=='table'){const t=document.createElement('table');t.className='pp-tb';const acc=o.color||th.acc[0];const rows=(o.rows||[]).slice(0,60);
  t.style.cssText=`font-family:"${th.bf}",Calibri,Arial,sans-serif;font-size:${o.fs||16}px;color:${th.fg}`;rows.forEach((r,i)=>{const tr=document.createElement('tr');r.slice(0,20).forEach(cv=>{const td=document.createElement(i==0&&o.hdr!==false?'th':'td');td.innerHTML=ppClean(cv);if(i==0&&o.hdr!==false){td.style.background=acc;td.style.color='#fff'}else if(o.band!==false&&i%2==0)td.style.background='rgba(127,127,127,.12)';tr.appendChild(td)});t.appendChild(tr)});
  if(o.line!==false)t.style.setProperty('--pp-tl',o.line||'rgba(127,127,127,.5)');el.appendChild(t)}
 else if(o.t=='chart'){const spec={...(o.chart||{}),w:o.w,h:o.h,bg:'transparent',fg:th.fg};el.innerHTML=offChartSVG(spec);const sv=el.firstElementChild;if(sv){sv.style.width='100%';sv.style.height='100%';sv.setAttribute('preserveAspectRatio','none')}}
 else if(o.t=='icon'){el.innerHTML=`<div class='pp-ic' style='font-size:${Math.min(o.w,o.h)*.85}px'>${ppEsc(o.icon||'⭐')}</div>`}
 return el}
function ppRender(D,s,opt){opt=opt||{};const[W,H]=ppSize(D);const th=PP_THEMES[D.theme]||PP_THEMES.office;const el=document.createElement('div');el.className='pp-slide';el.style.cssText=`width:${W}px;height:${H}px;background:${ppBgCss(D,s)};color:${th.fg}`;
 if(th.band&&!(s.bg))el.insertAdjacentHTML('beforeend',`<div class='pp-band' style='background:${th.band}'></div>`);
 for(const o of s.objs||[])el.appendChild(ppObjEl(D,s,o,opt));
 const M=D.master||{};const idx=D.slides.indexOf(s)+1;const foot=[];if(M.footer)foot.push(['pp-ff',M.footer]);if(M.date)foot.push(['pp-fd',new Date().toLocaleDateString()]);if(M.num&&!(s.layout=='title'&&M.numSkip!==false))foot.push(['pp-fn',String(idx)]);
 for(const[c,t]of foot){const f=document.createElement('div');f.className='pp-foot '+c;f.textContent=t;f.style.color=th.fg;el.appendChild(f)}
 if(M.logo){const im=document.createElement('img');im.className='pp-logo';im.src=M.logo;el.appendChild(im)}
 return el}
